/**
 * Full-flow (walking-skeleton) canary for the Maze Game Platform (task 9.2, D8).
 *
 * This canary walks the whole authenticated slice every 30 minutes (schedule set in the
 * CDK construct, `infra/observability.ts`), using a **reserved synthetic account** and
 * cleaning up after itself so it never accretes data on the one live leaderboard:
 *
 *   sign in  →  submit a validated score  →  read it back (`GET /scores/me`)
 *            →  see it on `GET /leaderboard`  →  self-clean via `DELETE /account/me`
 *
 * ## Credentials are sourced at runtime, never committed (R11.4)
 *
 * The synthetic account's password is NOT in this file, not in the CDK template, and not a
 * plaintext canary env var. The CDK construct grants this canary's execution role read
 * access to exactly one SSM Parameter Store SecureString and passes its **name** in
 * `MAZE_SYNTHETIC_CREDENTIAL_PARAM`. At runtime the canary fetches the value with
 * `ssm:GetParameter` (WithDecryption). The parameter's value is provisioned out of band at
 * deploy time (see the construct doc + the task's deploy-time follow-up); until then the
 * canary fails closed, which is the correct signal that the secret is unprovisioned.
 *
 * Other configuration is injected as plaintext env vars (no secret material):
 *  - `MAZE_API_BASE_URL`               — base HTTPS URL of the shared HTTP API.
 *  - `MAZE_COGNITO_USER_POOL_ID`       — the shared Cognito user pool id.
 *  - `MAZE_COGNITO_CLIENT_ID`          — the SPA app client id (public, no secret).
 *  - `MAZE_SYNTHETIC_USERNAME`         — the reserved synthetic account's email/username.
 *  - `MAZE_SYNTHETIC_CREDENTIAL_PARAM` — the SSM parameter NAME holding its password.
 *  - `MAZE_CANARY_SEED`               — a fixed, known-solvable maze seed.
 *
 * ## A valid run is built the same way the seam test builds one
 *
 * The server validates a submission by rebuilding the maze from `mazeParams` (size + seed)
 * and replaying the moves through the shared core (`validateSubmission`, R4.6). This canary
 * reproduces the *identical* maze with the same seeded PRNG (`mulberry32`) and the same
 * recursive-backtracker generation the validator uses, then breadth-first solves it and
 * turns the path into `Direction`s — mirroring
 * `src/server/handlers/scoresApi.integration.test.ts`. It relies on nothing private to the
 * server: same seed, same generation, same maze. The maze is kept small so the run is fast
 * and cheap.
 *
 * The runtime provides `Synthetics`/`SyntheticsLogger` and the AWS SDK v3 (`@aws-sdk/*`)
 * ambiently. Cognito sign-in uses the SRP flow the pool enables (USER_SRP_AUTH); the
 * plaintext USER_PASSWORD flow is deliberately not enabled on the pool.
 */
const synthetics = require("Synthetics");
const log = require("SyntheticsLogger");
const https = require("https");
const {
  CognitoIdentityProviderClient,
  InitiateAuthCommand,
  RespondToAuthChallengeCommand,
} = require("@aws-sdk/client-cognito-identity-provider");
const { SSMClient, GetParameterCommand } = require("@aws-sdk/client-ssm");
const { SRPClient, calculateSignature, getNowString } = require("amazon-user-pool-srp-client");

/** Maze size for the synthetic run. Small enough to solve fast, real enough to be a maze. */
const MAZE_ROWS = 7;
const MAZE_COLUMNS = 7;
/** A comfortable limit so a short solved run is never scored as a time loss. */
const TIME_LIMIT_SECONDS = 60;

/** Read a required canary environment variable, failing loudly if the wiring is missing. */
function requireEnv(name) {
  const value = process.env[name];
  if (value === undefined || value === "") {
    throw new Error(`missing required canary env var: ${name}`);
  }
  return value;
}

/**
 * A tiny deterministic PRNG (mulberry32) — byte-for-byte the one `validateSubmission`
 * seeds maze generation with, so the canary rebuilds the identical maze the server will.
 */
function mulberry32(seed) {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// --- Maze generation + solve (a faithful port of the shared core the server replays) -----
// Cells: 0 = wall, 1 = path. This is a byte-for-byte port of the Phase 1
// `RecursiveBacktrackerGenerator` (src/core/RecursiveBacktrackerGenerator.ts) — the exact
// generator `validateSubmission` rebuilds the maze with. The server accepts a submission
// only if the moves replay to a win on *its* maze, so this port MUST match the real
// generator move for move: same carve-cell lattice on EVEN coordinates, `start = {0,0}`,
// `exit` at the largest even coordinate below each dimension, and — critically — the same
// rng draw order (a Fisher-Yates shuffle of the four carve steps per cell, then take the
// first unvisited). An earlier version hand-rolled a different odd-cell lattice with a
// different rng-consumption pattern; it built a *different* maze, so its solution replayed
// to `not-a-win` and every submission was rejected 400.

/** Carve cells sit two grid steps apart, with a wall cell between them (mirrors CELL_SPACING). */
const CELL_SPACING = 2;

/** The four orthogonal cell-to-cell carve steps, in the same order as the core's CARVE_STEPS. */
const CARVE_STEPS = [
  { dRow: -CELL_SPACING, dColumn: 0 },
  { dRow: CELL_SPACING, dColumn: 0 },
  { dRow: 0, dColumn: -CELL_SPACING },
  { dRow: 0, dColumn: CELL_SPACING },
];

/** The largest even number strictly less than `size` — the core's `largestEvenBelow`. */
function largestEvenBelow(size) {
  const last = size - 1;
  return last % 2 === 0 ? last : last - 1;
}

/**
 * A copy of CARVE_STEPS shuffled with the same deterministic Fisher-Yates draw the core
 * uses, so the rng is consumed in the identical order and the carved maze is identical.
 */
function shuffledSteps(rng) {
  const steps = [...CARVE_STEPS];
  for (let i = steps.length - 1; i > 0; i -= 1) {
    const j = Math.floor(rng() * (i + 1));
    const temp = steps[i];
    steps[i] = steps[j];
    steps[j] = temp;
  }
  return steps;
}

function generateMaze(rows, columns, rng) {
  const grid = Array.from({ length: rows }, () => new Array(columns).fill(0));
  // The core carves from the top-left cell {0,0} and marks the largest even bottom-right
  // cell as the exit; both are on the even-coordinate carve lattice.
  const start = { row: 0, column: 0 };
  const exit = { row: largestEvenBelow(rows), column: largestEvenBelow(columns) };
  const key = (p) => `${p.row},${p.column}`;
  const carvable = (p) => p.row >= 0 && p.row < rows && p.column >= 0 && p.column < columns;

  const visited = new Set([key(start)]);
  const stack = [start];
  grid[start.row][start.column] = 1;

  while (stack.length > 0) {
    const current = stack[stack.length - 1];
    let next;
    for (const step of shuffledSteps(rng)) {
      const candidate = { row: current.row + step.dRow, column: current.column + step.dColumn };
      if (carvable(candidate) && !visited.has(key(candidate))) {
        next = candidate;
        break;
      }
    }
    if (next === undefined) {
      stack.pop();
      continue;
    }
    // Knock out the wall cell between the two carve cells, then descend.
    grid[(current.row + next.row) / 2][(current.column + next.column) / 2] = 1;
    grid[next.row][next.column] = 1;
    visited.add(key(next));
    stack.push(next);
  }

  return { grid, rows, columns, start, exit };
}

const MOVES = [
  { direction: "Up", dRow: -1, dColumn: 0 },
  { direction: "Down", dRow: 1, dColumn: 0 },
  { direction: "Left", dRow: 0, dColumn: -1 },
  { direction: "Right", dRow: 0, dColumn: 1 },
];

function solve(maze) {
  const key = (p) => `${p.row},${p.column}`;
  const inBounds = (p) =>
    p.row >= 0 && p.row < maze.rows && p.column >= 0 && p.column < maze.columns;
  const isPath = (p) => maze.grid[p.row] && maze.grid[p.row][p.column] === 1;
  const parents = new Map();
  const visited = new Set([key(maze.start)]);
  const queue = [maze.start];
  while (queue.length > 0) {
    const current = queue.shift();
    if (current.row === maze.exit.row && current.column === maze.exit.column) {
      const directions = [];
      let cursor = current;
      while (cursor.row !== maze.start.row || cursor.column !== maze.start.column) {
        const step = parents.get(key(cursor));
        directions.push(step.direction);
        cursor = step.from;
      }
      return directions.reverse();
    }
    for (const move of MOVES) {
      const next = { row: current.row + move.dRow, column: current.column + move.dColumn };
      if (!inBounds(next) || !isPath(next) || visited.has(key(next))) {
        continue;
      }
      visited.add(key(next));
      parents.set(key(next), { from: current, direction: move.direction });
      queue.push(next);
    }
  }
  throw new Error("no start-to-exit path — maze invariant violated");
}

// --- SSM-sourced credential --------------------------------------------------------------

async function fetchSyntheticPassword(parameterName) {
  const ssm = new SSMClient({});
  const out = await ssm.send(
    new GetParameterCommand({ Name: parameterName, WithDecryption: true }),
  );
  const value = out.Parameter && out.Parameter.Value;
  if (!value) {
    throw new Error(`synthetic credential parameter ${parameterName} is empty/unprovisioned`);
  }
  return value;
}

// --- Cognito SRP sign-in -----------------------------------------------------------------

async function signIn(userPoolId, clientId, username, password) {
  const poolName = userPoolId.split("_")[1];
  const srp = new SRPClient(poolName);
  const srpA = srp.calculateA();
  const cognito = new CognitoIdentityProviderClient({});

  const init = await cognito.send(
    new InitiateAuthCommand({
      AuthFlow: "USER_SRP_AUTH",
      ClientId: clientId,
      AuthParameters: { USERNAME: username, SRP_A: srpA },
    }),
  );
  const ch = init.ChallengeParameters;
  const hkdf = srp.getPasswordAuthenticationKey(
    ch.USER_ID_FOR_SRP,
    password,
    ch.SRP_B,
    ch.SALT,
  );
  const dateNow = getNowString();
  const signature = calculateSignature(
    hkdf,
    poolName,
    ch.USER_ID_FOR_SRP,
    ch.SECRET_BLOCK,
    dateNow,
  );
  const resp = await cognito.send(
    new RespondToAuthChallengeCommand({
      ChallengeName: "PASSWORD_VERIFIER",
      ClientId: clientId,
      ChallengeResponses: {
        PASSWORD_CLAIM_SIGNATURE: signature,
        PASSWORD_CLAIM_SECRET_BLOCK: ch.SECRET_BLOCK,
        TIMESTAMP: dateNow,
        USERNAME: ch.USER_ID_FOR_SRP,
      },
    }),
  );
  const token = resp.AuthenticationResult && resp.AuthenticationResult.AccessToken;
  if (!token) {
    throw new Error("sign-in did not return an access token");
  }
  return token;
}

// --- Authenticated JSON request against the real API -------------------------------------

function apiRequest(baseUrl, method, path, token, body) {
  const url = new URL(`${baseUrl}${path}`);
  const payload = body === undefined ? undefined : JSON.stringify(body);
  const options = {
    hostname: url.hostname,
    port: url.port === "" ? 443 : Number(url.port),
    path: `${url.pathname}${url.search}`,
    method,
    headers: {
      authorization: `Bearer ${token}`,
      ...(payload === undefined ? {} : { "content-type": "application/json" }),
    },
  };
  return new Promise((resolve, reject) => {
    const req = https.request(options, (res) => {
      let text = "";
      res.on("data", (chunk) => {
        text += chunk;
      });
      res.on("end", () => {
        let parsed = null;
        if (text.length > 0) {
          try {
            parsed = JSON.parse(text);
          } catch {
            parsed = text;
          }
        }
        resolve({ status: res.statusCode, body: parsed });
      });
    });
    req.on("error", reject);
    if (payload !== undefined) {
      req.write(payload);
    }
    req.end();
  });
}

function scopeQuery(params) {
  return (
    `?rows=${params.rows}&columns=${params.columns}` +
    `&seed=${params.seed}&timeLimitSeconds=${params.timeLimitSeconds}`
  );
}

const fullFlow = async function () {
  const baseUrl = requireEnv("MAZE_API_BASE_URL").replace(/\/+$/, "");
  const userPoolId = requireEnv("MAZE_COGNITO_USER_POOL_ID");
  const clientId = requireEnv("MAZE_COGNITO_CLIENT_ID");
  const username = requireEnv("MAZE_SYNTHETIC_USERNAME");
  const credentialParam = requireEnv("MAZE_SYNTHETIC_CREDENTIAL_PARAM");
  const seed = Number(requireEnv("MAZE_CANARY_SEED"));

  const params = {
    rows: MAZE_ROWS,
    columns: MAZE_COLUMNS,
    seed,
    timeLimitSeconds: TIME_LIMIT_SECONDS,
  };

  // (0) source the reserved account's password from SSM at runtime — never committed.
  const password = await synthetics.executeStep("fetch-credential", async () =>
    fetchSyntheticPassword(credentialParam),
  );

  // (1) sign in as the reserved synthetic account (SRP).
  const token = await synthetics.executeStep("sign-in", async () =>
    signIn(userPoolId, clientId, username, password),
  );

  // (2) submit a VALID run: rebuild the identical maze from seed, solve it, submit.
  const moves = solve(generateMaze(params.rows, params.columns, mulberry32(params.seed)));
  const submitted = await synthetics.executeStep("submit-score", async () => {
    const res = await apiRequest(baseUrl, "POST", "/scores", token, {
      mazeParams: params,
      moves,
      clientElapsedMs: 1234,
      idempotencyKey: `canary-${params.seed}-${Date.now()}`,
    });
    if (res.status !== 201) {
      throw new Error(`submit expected 201, got ${res.status}`);
    }
    return res.body;
  });
  log.info(`submitted score: persisted=${submitted && submitted.persisted}`);

  // (3) read it back through the caller's own history.
  await synthetics.executeStep("read-back", async () => {
    const res = await apiRequest(baseUrl, "GET", "/scores/me", token);
    if (res.status !== 200) {
      throw new Error(`read-back expected 200, got ${res.status}`);
    }
    const items = (res.body && res.body.items) || [];
    if (!items.some((s) => s.mazeParams && s.mazeParams.seed === params.seed)) {
      throw new Error("submitted score not found in own history");
    }
  });

  // (4) see it on the public leaderboard for this scope.
  await synthetics.executeStep("leaderboard", async () => {
    const res = await apiRequest(baseUrl, "GET", `/leaderboard${scopeQuery(params)}`, token);
    if (res.status !== 200) {
      throw new Error(`leaderboard expected 200, got ${res.status}`);
    }
    const standings = (res.body && res.body.standings) || [];
    if (standings.length === 0) {
      throw new Error("submitted score not visible on leaderboard");
    }
  });

  // (5) self-clean: erase the synthetic account's own data via the account-deletion path
  // (task 12.2, R11.5), so the run leaves no residue on the one live leaderboard. Run in a
  // finally-style step so cleanup happens even if a later assertion above threw earlier is
  // not applicable — this is the last step and always runs on the success path.
  await synthetics.executeStep("self-clean", async () => {
    const res = await apiRequest(baseUrl, "DELETE", "/account/me", token);
    if (res.status !== 200 && res.status !== 204) {
      throw new Error(`self-clean expected 200/204, got ${res.status}`);
    }
  });
};

exports.handler = async function () {
  return await fullFlow();
};
